(()=>{const result={},root=document.documentElement,old=root.style.fontSize;root.style.fontSize='20px';const parent=document.createElement('div');parent.style.fontSize='30px';document.body.append(parent);for(const value of ['1rem','1.5em','50%','12pt','1pc','2.54cm','25.4mm','101.6q','1in','medium','small','large','smaller','larger','inherit','initial','unset','calc(1rem + 2px)']){const child=document.createElement('div');child.style.fontSize=value;parent.append(child);result[value]=getComputedStyle(child).fontSize;child.remove()}const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg'),text=document.createElementNS(ns,'text');parent.append(svg);svg.append(text);text.textContent='AAAA';const bbox=()=>{const b=text.getBBox();return JSON.stringify([b.x,b.y,b.width,b.height])};text.setAttribute('font-size','1rem');const rem=bbox();result.svgComputed=getComputedStyle(text).fontSize;text.setAttribute('font-size','20px');result.svgEquivalent=rem===bbox();root.style.fontSize='24px';text.setAttribute('font-size','1rem');const changed=bbox();text.setAttribute('font-size','24px');result.svgRootMutation=changed===bbox()&&changed!==rem;text.style.fontSize='12px';result.svgCSSWins=getComputedStyle(text).fontSize;text.style.fontSize='0px';result.svgZero=text.getComputedTextLength();root.style.fontSize='2rem';result.root=getComputedStyle(root).fontSize;parent.remove();root.style.fontSize=old;return result})()